import{_ as l}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as o,C as n,c as _,o as h,al as i,j as a,a as t,G as d}from"./chunks/framework.D8UyiDWg.js";const A=JSON.parse('{"title":"Режим зльоту (з фіксованим крилом)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_fw/takeoff.md","filePath":"uk/flight_modes_fw/takeoff.md"}'),f={name:"uk/flight_modes_fw/takeoff.md"},c={class:"info custom-block"};function s(m,e,p,u,T,F){const r=n("Badge");return h(),_("div",null,[e[6]||(e[6]=i('<h1 id="режим-зльоту-з-фіксованим-крилом" tabindex="-1">Режим зльоту (з фіксованим крилом) <a class="header-anchor" href="#режим-зльоту-з-фіксованим-крилом" aria-label="Permalink to &quot;Режим зльоту (з фіксованим крилом)&quot;">​</a></h1><img src="'+l+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Takeoff</em> flight mode causes the vehicle to take off to a specified height and then enter <a href="./../flight_modes_fw/takeoff.html">Hold mode</a>.</p><p>Vehicles are <a href="#catapult-hand-launch">hand or catapult launched</a> by default, but can also be <a href="#RWTO_TKOFF">configured</a> to use a <a href="#runway-takeoff">runway takeoff</a> when supported by the hardware.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Режим автоматичний - для керування апаратом не потрібно втручання користувача.</li><li>Mode requires at least a valid altitude estimation. <ul><li>Flying vehicles can&#39;t switch to this mode without valid altitude.</li><li>Flying vehicles will failsafe if they lose the altitude estimate.</li><li>Disarmed vehicles can switch to mode without valid altitude estimate but can&#39;t arm.</li></ul></li><li>Перемикачі радіокерування можна використовувати для зміни режимів польоту.</li><li>Рух стіка радіокерування ігнорується при зліті за допомогою катапульти, але може бути використана для легкого перекочування транспортного засобу при зльоті зі злітної смуги.</li><li>The <a href="./../config/safety.html#failure-detector">Failure Detector</a> will automatically stop the engines if there is a problem on takeoff.</li></ul></div><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>Takeoff mode (and <a href="./../flight_modes_fw/mission.html#mission-takeoff">fixed wing mission takeoff</a>) has two modalities: <a href="#catapult-hand-launch">catapult/hand-launch</a> or <a href="#runway-takeoff">runway takeoff</a> (hardware-dependent). The mode defaults to catapult/hand launch, but can be set to runway takeoff by setting <a href="#RWTO_TKOFF">RWTO_TKOFF</a> to 1.</p><p>To use <em>Takeoff mode</em> you first switch to the mode, and then arm the vehicle (or send the <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a> command which does both). Прискорення запуску з руки/катапульти спричиняє запуск двигунів. Для запуску на злітну смугу мотори автоматично посилюються, як тільки транспортний засіб був увімкнений.</p><p>Незалежно від модальності, шлях польоту (початкова точка та курс взльоту) та висота дозволу визначені:</p><ul><li>Точкою виходу є позиція транспортного засобу, коли спочатку ввімкнений режим зльоту.</li><li>The course is set to the vehicle heading on arming by default. If a valid waypoint latitude/longitude is set the vehicle will instead track towards the waypoint.</li><li>The clearance altitude is set to <a href="#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a> by default. If a valid waypoint altitude is set is set the vehicle will instead use it as the clearance altitude.</li></ul><p>By default, on takeoff the aircraft will follow the line defined by the starting point and course, climbing at the maximum climb rate (<a href="./../advanced_config/parameter_reference.html#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a>) until reaching the clearance altitude. Reaching the clearance altitude causes the vehicle to enter <a href="./../flight_modes_fw/takeoff.html">Hold mode</a>.</p><p>If a valid waypoint target is set, using <code>MAV_CMD_NAV_TAKEOFF</code> or the <a href="./../msg_docs/VehicleCommand.html">VehicleCommand</a> uORB topic, the vehicle will instead track towards the waypoint, and enter <a href="./../flight_modes_fw/takeoff.html">Hold mode</a> after reaching the waypoint altitude (within the acceptance radius).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the local position is invalid or becomes invalid while executing the takeoff, the controller is not able to track a course setpoint and will instead proceed climbing while keeping the wings level until the clearance altitude is reached.</p></div>',13)),a("div",c,[e[5]||(e[5]=a("p",{class:"custom-block-title"},"INFO",-1)),a("ul",null,[a("li",null,[e[0]||(e[0]=t("Takeoff towards a target position was added in ")),d(r,{type:"tip",text:"main (planned for: PX4 v1.17)"}),e[1]||(e[1]=t("."))]),a("li",null,[e[2]||(e[2]=t("Holding wings level and ascending to clearance attitude when local position is invalid during takeoff was added in ")),d(r,{type:"tip",text:"main (planned for: PX4 v1.17)"}),e[3]||(e[3]=t("."))]),e[4]||(e[4]=a("li",null,[t("QGroundControl does not support "),a("code",null,"MAV_CMD_NAV_TAKEOFF"),t(" (at time of writing).")],-1))])]),e[7]||(e[7]=i('<h3 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h3><p>Параметри, які впливають як на катапульту/ручний старт, так і на зліт зі злітно-посадкової смуги:</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Опис</th></tr></thead><tbody><tr><td><a id="MIS_TAKEOFF_ALT"></a><a href="./../advanced_config/parameter_reference.html#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a></td><td>This is the relative altitude (above launch altitude) the system will take off to if not otherwise specified. takeoff.</td></tr><tr><td><a id="FW_TKO_AIRSPD"></a><a href="./../advanced_config/parameter_reference.html#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a></td><td>Takeoff airspeed (is set to <a href="./../advanced_config/parameter_reference.html#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> if not defined by operator)</td></tr><tr><td><a id="FW_TKO_PITCH_MIN"></a><a href="./../advanced_config/parameter_reference.html#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a></td><td>Це мінімальний кут нахилу заданий під час фази зльоту</td></tr><tr><td><a id="FW_T_CLMB_MAX"></a><a href="./../advanced_config/parameter_reference.html#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a></td><td>Climb rate setpoint during climbout to takeoff altitude.</td></tr><tr><td><a id="FW_FLAPS_TO_SCL"></a><a href="./../advanced_config/parameter_reference.html#FW_FLAPS_TO_SCL">FW_FLAPS_TO_SCL</a></td><td>Налаштування закрилок під час зльоту</td></tr><tr><td><a id="FW_AIRSPD_FLP_SC"></a><a href="./../advanced_config/parameter_reference.html#FW_AIRSPD_FLP_SC">FW_AIRSPD_FLP_SC</a></td><td>Factor applied to the minimum airspeed when flaps are fully deployed. Needed if <a href="#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a> is below <a href="./../advanced_config/parameter_reference.html#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a>.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The vehicle always respects normal FW max/min throttle settings during takeoff (<a href="./../advanced_config/parameter_reference.html#FW_THR_MIN">FW_THR_MIN</a>, <a href="./../advanced_config/parameter_reference.html#FW_THR_MAX">FW_THR_MAX</a>).</p></div><h2 id="hand_launch" tabindex="-1">Catapult/Hand Launch <a class="header-anchor" href="#hand_launch" aria-label="Permalink to &quot;Catapult/Hand Launch {#hand_launch}&quot;">​</a></h2><p>In <em>catapult/hand-launch mode</em> the vehicle waits to detect launch (based on acceleration trigger). On launch it enables the motor(s) and climbs with the maximum climb rate <a href="#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a> while keeping the pitch setpoint above <a href="#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a>. Once it reaches <a href="#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a> it will automatically switch to <a href="./../flight_modes_fw/hold.html">Hold mode</a> and loiter.</p><p>Всі рухи стіку радіоуправління ігноруються під час повного взлітного процесу.</p><p>Для запуску в цьому режимі:</p><ol><li>Увімкніть дрон</li><li>Put the vehicle into <em>Takeoff mode</em></li><li>Запустіть / киньте транспортний засіб (міцно) безпосередньо у вітер. Ви також можете спершу потрясти транспортний засіб, зачекати, поки рушить двигун, а потім кинути його</li></ol><h3 id="параметри-виявник-запуску" tabindex="-1">Параметри (виявник запуску) <a class="header-anchor" href="#параметри-виявник-запуску" aria-label="Permalink to &quot;Параметри (виявник запуску)&quot;">​</a></h3><p>The <em>launch detector</em> is affected by the following parameters:</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Опис</th></tr></thead><tbody><tr><td><a id="FW_LAUN_DETCN_ON"></a><a href="./../advanced_config/parameter_reference.html#FW_LAUN_DETCN_ON">FW_LAUN_DETCN_ON</a></td><td>Увімкнути автоматичне визначення запуску. Якщо вимкнені двигуни обертаються при підготовці до польоту</td></tr><tr><td><a id="FW_LAUN_AC_THLD"></a><a href="./../advanced_config/parameter_reference.html#FW_LAUN_AC_THLD">FW_LAUN_AC_THLD</a></td><td>Поріг прискорення (прискорення в напрямку руху тіла повинно бути вище цієї величини)</td></tr><tr><td><a id="FW_LAUN_AC_T"></a><a href="./../advanced_config/parameter_reference.html#FW_LAUN_AC_T">FW_LAUN_AC_T</a></td><td>Час спрацьовування (прискорення повинно бути вище порогу на цю кількість секунд)</td></tr><tr><td><a id="FW_LAUN_MOT_DEL"></a><a href="./../advanced_config/parameter_reference.html#FW_LAUN_MOT_DEL">FW_LAUN_MOT_DEL</a></td><td>Затримка від виявлення запуску до відкручування мотору</td></tr></tbody></table><h2 id="runway_launch" tabindex="-1">Runway Takeoff <a class="header-anchor" href="#runway_launch" aria-label="Permalink to &quot;Runway Takeoff {#runway_launch}&quot;">​</a></h2><p>Зліт зі злітної смуги можна використовувати тільки для транспортних засобів з посадковим шасі та керованим колесом. You will first need to enable the wheel controller using the parameter <a href="#FW_W_EN">FW_W_EN</a>.</p><p>Транспортний засіб повинен бути в центрі та вирівняний по злітній смузі, коли починається зльот. The operator can &quot;nudge&quot; the vehicle while on the runway to help keeping it centered and aligned (see <a href="./../advanced_config/parameter_reference.html#RWTO_NUDGE">RWTO_NUDGE</a>).</p><p>The <em>runway takeoff mode</em> has the following phases:</p><ol><li><strong>Throttle ramp</strong>: Throttle is ramped up within <a href="./../advanced_config/parameter_reference.html#RWTO_RAMP_TIME">RWTO_RAMP_TIME</a> to <a href="./../advanced_config/parameter_reference.html#RWTO_MAX_THR">RWTO_MAX_THR</a>.</li><li><strong>Clamped to runway</strong>: Pitch fixed, no roll and takeoff path controlled until the rotation airspeed (<a href="./../advanced_config/parameter_reference.html#RWTO_ROT_AIRSPD">RWTO_ROT_AIRSPD</a>) is reached. Оператор може підганяти транспортний засіб ліворуч/праворуч за допомогою стіка рискання.</li><li><strong>Climbout</strong>: Increase pitch setpoint and climb to takeoff altitude. Щоб уникнути ударів крил, контролер буде тримати встановлений кут кочення заблокованим на 0, коли близько до землі, а потім поступово дозволить більше кочення під час підйому. It is based on the vehicle geometry as configured in <a href="#FW_WING_SPAN">FW_WING_SPAN</a> and <a href="#FW_WING_HEIGHT">FW_WING_HEIGHT</a>.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For a smooth takeoff, the runway wheel controller possibly needs to be tuned. It consists of a rate controller (P-I-FF-controller with the parameters <a href="./../advanced_config/parameter_reference.html#FW_WR_P">FW_WR_P</a>, <a href="./../advanced_config/parameter_reference.html#FW_WR_I">FW_WR_I</a>, <a href="./../advanced_config/parameter_reference.html#FW_WR_FF">FW_WR_FF</a>).</p></div><h3 id="параметри-зліт-зі-злітноі-смуги" tabindex="-1">Параметри (зліт зі злітної смуги) <a class="header-anchor" href="#параметри-зліт-зі-злітноі-смуги" aria-label="Permalink to &quot;Параметри (зліт зі злітної смуги)&quot;">​</a></h3><p>Зліт зі злітної смуги залежить від наступних параметрів:</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Опис</th></tr></thead><tbody><tr><td><a id="RWTO_TKOFF"></a><a href="./../advanced_config/parameter_reference.html#RWTO_TKOFF">RWTO_TKOFF</a></td><td>Увімкніть зліт по взлітній смузі</td></tr><tr><td><a id="FW_W_EN"></a><a href="./../advanced_config/parameter_reference.html#FW_W_EN">FW_W_EN</a></td><td>Увімкнути контролер колеса</td></tr><tr><td><a id="RWTO_MAX_THR"></a><a href="./../advanced_config/parameter_reference.html#RWTO_MAX_THR">RWTO_MAX_THR</a></td><td>Максимальне розгін під час взліту зі злітної смуги</td></tr><tr><td><a id="RWTO_RAMP_TIME"></a><a href="./../advanced_config/parameter_reference.html#RWTO_RAMP_TIME">RWTO_RAMP_TIME</a></td><td>Час прискорення ручки газу</td></tr><tr><td><a id="RWTO_ROT_AIRSPD"></a><a href="./../advanced_config/parameter_reference.html#RWTO_ROT_AIRSPD">RWTO_ROT_AIRSPD</a></td><td>Поріг швидкості для початку підняття (нахилення вгору). Якщо не налаштовано оператором, встановлюється на 0,9*FW_TKO_AIRSPD.</td></tr><tr><td><a id="RWTO_ROT_TIME"></a><a href="./../advanced_config/parameter_reference.html#RWTO_ROT_TIME">RWTO_ROT_TIME</a></td><td>Це час, який необхідно лінійно нарощувати обмеження швидкості прийому під час обертання на зльоті.</td></tr><tr><td><a id="FW_TKO_AIRSPD"></a><a href="./../advanced_config/parameter_reference.html#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a></td><td>Задана швидкість під час розгону під час зльоту (після відкочування). Якщо не налаштовано оператором, встановлюється на FW_AIRSPD_MIN.</td></tr><tr><td><a id="RWTO_NUDGE"></a><a href="./../advanced_config/parameter_reference.html#RWTO_NUDGE">RWTO_NUDGE</a></td><td>Увімкніть керування колесом під час руху по злітній смузі</td></tr><tr><td><a id="FW_WING_SPAN"></a><a href="./../advanced_config/parameter_reference.html#FW_WING_SPAN">FW_WING_SPAN</a></td><td>Розмах крила транспортного засобу. Використовується для запобігання ударів крилом.</td></tr><tr><td><a id="FW_WING_HEIGHT"></a><a href="./../advanced_config/parameter_reference.html#FW_WING_HEIGHT">FW_WING_HEIGHT</a></td><td>Висота крил над землею (дорожній просвіт). Використовується для запобігання ударів крилом.</td></tr></tbody></table><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/takeoff.html">Takeoff Mode (MC)</a></li><li><a href="./../flight_modes_fw/mission.html#mission-takeoff">Planning a mission takeoff</a></li></ul>',23))])}const I=o(f,[["render",s]]);export{A as __pageData,I as default};
